export function findDataGovernancePoliciesById(id: string): GovernancePolicyRecord | undefined {
  return GOVERNANCE_POLICIES_DATABASE.find(item => item.id === id);
}

export function getAllDataGovernancePoliciesRecords(): GovernancePolicyRecord[] {
  return GOVERNANCE_POLICIES_DATABASE;
}

export function filterDataGovernancePoliciesByPredicate(predicate: (item: GovernancePolicyRecord) => boolean): GovernancePolicyRecord[] {
  return GOVERNANCE_POLICIES_DATABASE.filter(predicate);
}

export function countDataGovernancePoliciesRecords(): number {
  return GOVERNANCE_POLICIES_DATABASE.length;
}
